python3 -c "
from PIL import Image
im = Image.open('/app/output/final_poster.png')
# Scan near title area to find text pixels
print('Scanning title area (x=220-500, y=160-250):')
for y in range(160, 250, 10):
    row_colors = set()
    for x in range(220, 500, 10):
        px = im.getpixel((x, y))
        if px != (250, 250, 248):
            row_colors.add(px)
    if row_colors:
        print(f'  y={y}: non-bg colors found: {row_colors}')
    else:
        print(f'  y={y}: all background')

# Also check if any dark pixels exist in the top section
print()
print('Scanning for dark (navy) pixels in title zone (x=220-800, y=150-300):')
dark_count = 0
for y in range(150, 300, 5):
    for x in range(220, 800, 5):
        px = im.getpixel((x, y))
        if sum(px) < 300:
            dark_count += 1
print(f'  Found {dark_count} dark pixels')
" 2>&1

